INSERT INTO "dataset_registry" VALUES(1,'apriori','apriori_standard_9tx','Giao dịch chuẩn — 9 giao dịch, 5 items','9 giao dịch mua hàng với 5 mặt hàng (I1..I5) — bộ dữ liệu kinh điển để minh họa từng bước thuật toán Apriori.','{"minsup": 0.2222, "minconf": 0.7}');
INSERT INTO "dataset_registry" VALUES(2,'apriori','apriori_grocery_4tx','Cửa hàng bách hóa — 4 giao dịch','4 giao dịch mua sắm với 4 mặt hàng thực phẩm — bài tập nhập môn về thuật toán vét cạn và Apriori.','{"minsup": 0.5, "minconf": 0.75}');
INSERT INTO "dataset_registry" VALUES(3,'apriori','apriori_daily_basket_5tx','Giỏ hàng hàng ngày — 5 giao dịch','5 giao dịch mua sắm ngày thường với 5 mặt hàng (Bread, Cornflakes...) — minh họa Apriori và biểu diễn vector nhị phân.','{"minsup": 0.6, "minconf": 0.75}');
INSERT INTO "dataset_registry" VALUES(4,'apriori','apriori_numeric_4tx','Mã hóa số — 4 giao dịch','4 giao dịch với các mặt hàng dạng số (1..5) — ví dụ sinh tập ứng cử viên Cₖ và tập phổ biến Lₖ.','{"minsup": 0.5, "minconf": 0.7}');
INSERT INTO "dataset_registry" VALUES(5,'apriori','apriori_letters_4tx','Chữ cái A-E — 4 giao dịch','4 giao dịch với 5 chữ cái — minh họa cơ sở mẫu điều kiện trong FP-Growth.','{"minsup": 0.5, "minconf": 0.7}');
INSERT INTO "dataset_registry" VALUES(6,'apriori','apriori_theory_8tx','Lý thuyết 8 giao dịch — a,b,c,d,e','8 giao dịch lý thuyết với 5 item (a..e) — định nghĩa tần suất, độ hỗ trợ, độ tin cậy, lift và leverage.','{"minsup": 0.375, "minconf": 0.8}');
INSERT INTO "dataset_registry" VALUES(7,'apriori','apriori_math_5tx','Bài tập toán học — 5 giao dịch, {a,b,c,d}','5 giao dịch với 4 item {a,b,c,d} — bài tập tìm tập phổ biến và luật kết hợp theo hướng toán học.','{"minsup": 0.25, "minconf": 0.75}');
INSERT INTO "dataset_registry" VALUES(8,'rough_set','roughset_relation_7obj','Bảng quan hệ 5 thuộc tính — 7 bản ghi','7 đối tượng với 5 thuộc tính điều kiện {A,B,C,D,E} — xác định phân hoạch tương đương và tìm các tập rút gọn tối giản.','{"condition_attrs": ["A", "B", "C", "D", "E"], "decision_attr": ""}');
INSERT INTO "dataset_registry" VALUES(9,'rough_set','roughset_playtennis_14obj','Hệ quyết định Chơi Tennis — 14 bản ghi','14 ngày quan sát thời tiết với 4 thuộc tính điều kiện và nhãn PlayTennis — minh họa vùng xấp xỉ và tập rút gọn quyết định.','{"condition_attrs": ["Outlook", "Temperature", "Humidity", "Wind"], "decision_attr": "PlayTennis"}');
INSERT INTO "dataset_registry" VALUES(10,'rough_set','roughset_weather_decision_8obj','Bảng quyết định Thời tiết — 8 đối tượng','8 ngày với 3 thuộc tính (Outlook, Temperature, Humidity) và nhãn quyết định — xác định IND(C) và sinh luật quyết định tối giản.','{"condition_attrs": ["Outlook", "Temperature", "Humidity"], "decision_attr": "Decision"}');
INSERT INTO "dataset_registry" VALUES(11,'rough_set','roughset_recruitment_8obj','Tuyển dụng — 8 ứng viên','8 ứng viên với bằng cấp, kinh nghiệm, tiếng Pháp và thư giới thiệu — hàm dạng chuẩn tắc hội đầy đủ, rồi rút gọn thành dạng chuẩn tắc tuyển để quyết định Accept/Reject.','{"condition_attrs": ["Diploma", "Experience", "French", "Reference"], "decision_attr": "Decision"}');
INSERT INTO "dataset_registry" VALUES(12,'id3','id3_buy_computer','Mua máy tính AllElectronics — 14 mẫu','14 khách hàng phân theo độ tuổi, thu nhập, tình trạng sinh viên và xếp loại tín dụng để dự đoán hành vi mua máy tính.','{"max_depth": 5, "decision_attr": "buys_computer"}');
INSERT INTO "dataset_registry" VALUES(13,'id3','id3_weather_play','Dự báo thời tiết chơi thể thao — 14 ngày','14 quan sát thời tiết theo 4 yếu tố (trời, nhiệt độ, độ ẩm, gió) để phân loại có nên ra ngoài chơi thể thao không.','{"max_depth": 5, "decision_attr": "Play"}');
INSERT INTO "dataset_registry" VALUES(14,'naive_bayes','id3_buy_computer','Mua máy tính AllElectronics — NB không làm trơn (14 mẫu)','Cùng bảng ID3 AllElectronics, Naïve Bayes không làm trơn dự đoán buys_computer.','{"decision_attr": "buys_computer"}');
INSERT INTO "dataset_registry" VALUES(15,'naive_bayes','id3_weather_play','Dự báo thời tiết — NB không làm trơn (14 ngày)','Cùng bảng ID3 thời tiết, Naïve Bayes không làm trơn dự đoán Play.','{"decision_attr": "Play"}');
INSERT INTO "dataset_registry" VALUES(16,'cart_gini','id3_weather_play','Dự báo thời tiết — CART Gini (14 ngày)','Cùng bộ dữ liệu thời tiết ID3, xây cây theo Gini Index.','{"max_depth": 5, "decision_attr": "Play"}');
INSERT INTO "dataset_registry" VALUES(17,'cart_gini','id3_buy_computer','Mua máy tính — CART Gini (14 mẫu)','Cùng bộ dữ liệu AllElectronics, xây cây theo Gini Index.','{"max_depth": 5, "decision_attr": "buys_computer"}');
INSERT INTO "dataset_registry" VALUES(18,'kmeans','kmeans_2d_7pts','Tọa độ 2D — 7 điểm (k=2, Euclide)','7 điểm phân bố trong mặt phẳng 2D, gom thành 2 cụm bằng khoảng cách Euclide (khởi tạo trọng tâm ngẫu nhiên).','{"k": 2, "distance": "euclidean", "init": "random", "max_iter": 20}');
INSERT INTO "dataset_registry" VALUES(19,'kmeans','kmeans_student_scores','Điểm học sinh 4 bài kiểm tra (k=3, Manhattan)','10 học sinh với điểm Quiz1, Bài giữa kỳ, Quiz2 và Bài cuối kỳ — gom nhóm theo năng lực bằng khoảng cách Manhattan.','{"k": 3, "distance": "manhattan", "init": "random", "max_iter": 20}');
INSERT INTO "dataset_registry" VALUES(20,'kmeans','kmeans_2d_9pts','Tọa độ 2D — 9 điểm (k=3, Euclide)','9 điểm trong mặt phẳng 2D, phân thành 3 cụm — kiểm chứng từng vòng lặp gán điểm và cập nhật trọng tâm.','{"k": 3, "distance": "euclidean", "init": "random", "max_iter": 20}');
